local config = {
  str_homestory_N23paixi_90040101_1_dialog_content = "Vice, sobre o que você me disse ontem...",
  str_homestory_N23paixi_90040101_2_dialog_content = "Eu dormi nele e acho que é realmente factível!",
  str_homestory_N23paixi_90040101_3_dialog_content = "Heheh, eu sabia que você me pegaria, PlayerName!",
  str_homestory_N23paixi_90040101_4_dialog_content = "Eu sei que já mantenho um diário todos os dias...",
  str_homestory_N23paixi_90040101_5_dialog_content = "mas ainda acho que seria melhor documentar nossas experiências em vídeo.",
  str_homestory_N23paixi_90040101_6_dialog_content = "Sim, passamos pelas coisas mais interessantes juntos.",
  str_homestory_N23paixi_90040101_7_dialog_content = "Exatamente!",
  str_homestory_N23paixi_90040101_8_dialog_content = "Se pudéssemos filmá-los de forma artística como um <color=#FFB400>filme</color>, isso seria incrível.",
  str_homestory_N23paixi_90040101_9_dialog_content = "Hum. Isso mesmo!",
  str_homestory_N23paixi_90040101_10_dialog_content = "Hum, falando nisso...",
  str_homestory_N23paixi_90040101_11_dialog_content = "Se queremos fazer um filme, precisamos fazer um <color=#FFB400>estúdio de filme</color> Primeira à direita?",
  str_homestory_N23paixi_90040101_12_dialog_content = "Eu acho.",
  str_homestory_N23paixi_90040101_13_dialog_content = "Acho que posso deixar as plantas arquitetônicas e outras coisas para você, Vice.",
  str_homestory_N23paixi_90040101_14_dialog_content = "Eu sei que você é bom nessas coisas.",
  str_homestory_N23paixi_90040101_15_dialog_content = "Huh? Bem, eu sei como desenhar plantas e outras coisas...",
  str_homestory_N23paixi_90040101_16_dialog_content = "Mas eu não sei nada sobre equipamentos de filmagem.",
  str_homestory_N23paixi_90040101_17_dialog_content = "O-o que?!",
  str_homestory_N23paixi_90040101_18_dialog_content = "Existem plantas mesmo que você não pode projetar?",
  str_homestory_N23paixi_90040101_19_dialog_content = "E-Ei! Isso é pra ser um elogio ou um insulto?",
  str_homestory_N23paixi_90040101_20_dialog_content = "Estou apenas chocado.",
  str_homestory_N23paixi_90040101_21_dialog_content = "Hmm... Filmes, um estúdio de cinema... equipamento de filmagem, um produtor...",
  str_homestory_N23paixi_90040101_22_dialog_content = "Produtor?",
  str_homestory_N23paixi_90040101_23_dialog_content = "Certo! Produtor!",
  str_homestory_N23paixi_90040101_24_dialog_content = "PlayerName, por que não perguntamos <color=#FFB400>Minos</color>?",
  str_homestory_N23paixi_90040101_25_dialog_content = "Quero dizer, ele tem experiência recente. Podemos totalmente pedir a ele para ajudar!",
  str_homestory_N23paixi_90040101_26_dialog_content = "Tem razão!",
  str_homestory_N23paixi_90040101_27_dialog_content = "Vamos perguntar a ele.",
  str_homestory_N23paixi_90040102_1_dialog_content = "Oi, Minos!",
  str_homestory_N23paixi_90040102_2_dialog_content = "Boa tarde, nobre PlayerName.",
  str_homestory_N23paixi_90040102_3_dialog_content = "Acontece que tenho uma pergunta para lhe fazer, se não se importar, é claro.",
  str_homestory_N23paixi_90040102_4_dialog_content = "Claro. Fico feliz em poder ajudar em qualquer coisa.",
  str_homestory_N23paixi_90040102_5_dialog_content = "Certo.",
  str_homestory_N23paixi_90040102_6_dialog_content = "As preferências alimentares de Miss Nina mudaram recentemente. Ela está realmente interessada <color=#FFB400>peixe</color> agora.",
  str_homestory_N23paixi_90040102_7_dialog_content = "Agora, normalmente eu deveria estar preparando suas refeições, já que sou seu mordomo.",
  str_homestory_N23paixi_90040102_8_dialog_content = "Mas, neste momento, estou tentando revisar e registrar minha experiência como produtor.",
  str_homestory_N23paixi_90040102_9_dialog_content = "Em vez de me distrair e passar para outra coisa no meio do caminho, espero poder terminar minha revisão primeiro.",
  str_homestory_N23paixi_90040102_10_dialog_content = "Mas se eu fizer isso, com certeza já terá passado da hora do almoço quando eu voltar com um peixe para cozinhar.",
  str_homestory_N23paixi_90040102_11_dialog_content = "Eu vejo. Então você quer que eu <color=#FFB400>pegar alguns peixes</color> para você, certo?",
  str_homestory_N23paixi_90040102_12_dialog_content = "Está correto. Eu ficaria grato se você pudesse reservar algum tempo para fazer isso por mim agora, PlayerName.",
  str_homestory_N23paixi_90040102_13_dialog_content = "É claro! Pode contar comigo!",
  str_homestory_N23paixi_90040102_X13_dialog_content = "Ah, quase esqueci de perguntar.",
  str_homestory_N23paixi_90040102_X14_dialog_content = "Que tipo de peixe você precisa?",
  str_homestory_N23paixi_90040102_X15_dialog_content = "Desculpas, eu deveria ter dito a você.",
  str_homestory_N23paixi_90040102_X16_dialog_content = "Ultimamente, Miss Nina tem gostado de Knifefish.",
  str_homestory_N23paixi_90040102_X17_dialog_content = "Pronto, entendi! Deixe para mim.",
  str_homestory_N23paixi_90040102_14_dialog_content = "A propósito, o que você quer dizer com \"revisão\"?",
  str_homestory_N23paixi_90040102_15_dialog_content = "Quero fazer um registro abrangente da minha experiência recente como produtor.",
  str_homestory_N23paixi_90040102_16_dialog_content = "Por exemplo, como um cenário é construído, o que é exigido da equipe para fazer um filme e como operar o equipamento necessário.",
  str_homestory_N23paixi_90040102_17_dialog_content = "Claro, não é porque eu sou algum fanático por filmes que estou fazendo isso.",
  str_homestory_N23paixi_90040102_18_dialog_content = "Eu só quero estar preparado se a Srta. Nina de repente se interessar por isso algum dia.<sprite=emo_mojing size=60 />",
  str_homestory_N23paixi_90040102_19_dialog_content = "Entendi.",
  str_homestory_N23paixi_90040102_20_dialog_content = "Na verdade, estou precisando dessa sua \"revisão\". É por isso que estou aqui.",
  str_homestory_N23paixi_90040102_21_dialog_content = "Depois que eu voltar com seu peixe, você pode me dizer o que é necessário para fazer um filme?",
  str_homestory_N23paixi_90040102_22_dialog_content = "É claro. Eu ficaria feliz em ajudar.",
  str_homestory_N23paixi_90040102_23_dialog_content = "Estarei esperando seu retorno, então.",
  str_homestory_N23paixi_90040103_1_dialog_content = "Isso foi muito mais rápido do que eu esperava.",
  str_homestory_N23paixi_90040103_2_dialog_content = "É claro! ({1}/{2})",
  str_homestory_N23paixi_90040103_5_dialog_content = "Obrigada. Eu vou retribuir com o que você precisa de mim.",
  str_homestory_N23paixi_90040103_6_dialog_content = "Eu completei minha revisão.",
  str_homestory_N23paixi_90040103_7_dialog_content = "Agora, deixe-me confirmar o que você quer de mim...",
  str_homestory_N23paixi_90040103_8_dialog_content = "Você quer fazer um estúdio de cinema em Cloud Gardens, sim?",
  str_homestory_N23paixi_90040103_9_dialog_content = "Isso mesmo.",
  str_homestory_N23paixi_90040103_10_dialog_content = "Mas eu realmente não sei que tipo de equipamento vamos precisar...",
  str_homestory_N23paixi_90040103_11_dialog_content = "Entendi.",
  str_homestory_N23paixi_90040103_12_dialog_content = "Anteriormente, consegui compilar uma lista de todas as coisas que você precisa para fazer um estúdio de cinema.",
  str_homestory_N23paixi_90040103_13_dialog_content = "Posso fornecer a maioria dos equipamentos e materiais de construção diretamente.",
  str_homestory_N23paixi_90040103_14_dialog_content = "Ahem, isso é claro porque os Andersens têm você em alta conta.",
  str_homestory_N23paixi_90040103_15_dialog_content = "No entanto, ainda preciso de alguns materiais para fazer o <color=#FFB400>cenários</color>.",
  str_homestory_N23paixi_90040103_16_dialog_content = "Cenários também são necessários para fazer filmes, certo?",
  str_homestory_N23paixi_90040103_17_dialog_content = "Está correto.",
  str_homestory_N23paixi_90040103_18_dialog_content = "Ah, então você precisa que eu junte alguns materiais para você!",
  str_homestory_N23paixi_90040103_19_dialog_content = "Sim. Eu vou precisar de você para reunir <color=#FFB400>10 madeira</color> para mim.",
  str_homestory_N23paixi_90040103_20_dialog_content = "Assim que tiver a madeira, posso começar a fazer os cenários.",
  str_homestory_N23paixi_90040103_21_dialog_content = "Eu também terei outras coisas preparadas para você.",
  str_homestory_N23paixi_90040103_22_dialog_content = "Isso é... incrível! Obrigado, Minos!",
  str_homestory_N23paixi_90040103_23_dialog_content = "Eu vou lá, então!",
  str_homestory_N23paixi_90040103_24_dialog_content = "Muito apreciado, PlayerName.",
  str_homestory_N23paixi_90040103_3_dialog_content = "Ainda tenho um pouco mais para pegar...",
  str_homestory_N23paixi_90040103_4_dialog_content = "Obrigado por todo o trabalho duro, PlayerName.",
  str_homestory_N23paixi_90040104_1_dialog_content = "Isso foi muito mais rápido do que eu esperava.",
  str_homestory_N23paixi_90040104_2_dialog_content = "É claro! ({1}/{2})",
  str_homestory_N23paixi_90040104_5_dialog_content = "Eu preparei tudo o que você vai precisar aqui.",
  str_homestory_N23paixi_90040104_6_dialog_content = "Vou precisar de algum tempo para polir esses cenários futuros...",
  str_homestory_N23paixi_90040104_7_dialog_content = "Você poderá vê-los em breve, e tudo o mais que você precisa para fazer filmes.",
  str_homestory_N23paixi_90040104_8_dialog_content = "Sou tão abençoado por ter um mordomo como você em Cloud Gardens, Minos!",
  str_homestory_N23paixi_90040104_9_dialog_content = "Estou honrado que você pense assim.",
  str_homestory_N23paixi_90040104_3_dialog_content = "Ainda preciso de um pouco mais...",
  str_homestory_N23paixi_90040104_4_dialog_content = "Obrigado por todo o seu trabalho árduo, PlayerName.",
  str_homestory_N23paixi_90040105_1_dialog_content = "Minos, você é realmente incrível! Tudo está feito!",
  str_homestory_N23paixi_90040105_X1_dialog_content = "Você me lisonjeia.",
  str_homestory_N23paixi_90040105_2_dialog_content = "Agora eu tenho que descobrir<sprite=emo_sikao size=60 /> onde devemos colocar nosso estúdio de cinema.",
  str_homestory_N23paixi_90040106_1_dialog_content = "Ufa! Agora que o local está definido, meu estúdio de cinema está realmente tomando forma.",
  str_homestory_N23paixi_90040106_2_dialog_content = "Mas as coisas aqui parecem precisar de alguma limpeza e organização.",
  str_homestory_N23paixi_90040106_3_dialog_content = "O estúdio de cinema deve estar funcionando quando tudo estiver limpo.",
  str_homestory_N23paixi_90040107_1_dialog_content = "Minos! Acabei de testar o equipamento...",
  str_homestory_N23paixi_90040107_2_dialog_content = "Eles são incríveis!",
  str_homestory_N23paixi_90040107_3_dialog_content = "Fico feliz em vê-lo tão emocionado.",
  str_homestory_N23paixi_90040107_4_dialog_content = "Na verdade, tenho mais uma coisa para você, se estiver disposto a aceitar.",
  str_homestory_N23paixi_90040107_5_dialog_content = "Aqui está um roteiro que recebi durante meu tempo como produtor.",
  str_homestory_N23paixi_90040107_6_dialog_content = "Agora que você tem um estúdio de cinema aqui, acho que pode ser de alguma utilidade para você.",
  str_homestory_N23paixi_90040107_7_dialog_content = "Claro, você pode me recusar se já tiver outra coisa em mente.",
  str_homestory_N23paixi_90040107_8_dialog_content = "De qualquer forma, acredito que esse script ainda pode servir como um bom modelo para referência.",
  str_homestory_N23paixi_90040107_9_dialog_content = "Isso é realmente útil!",
  str_homestory_N23paixi_90040107_10_dialog_content = "Prometo fazer bom uso dela, Minos!",
  str_homestory_N23paixi_90040107_11_dialog_content = "Eu... realmente não sei como te agradecer.",
  str_homestory_N23paixi_90040107_12_dialog_content = "De nada, PlayerName.",
  str_homestory_N23paixi_90040107_13_dialog_content = "Você vai me dizer que é apenas mais um dos seus deveres esperados?",
  str_homestory_N23paixi_90040107_14_dialog_content = "Por uma vez, apenas aceite meus agradecimentos. Por favor?",
  str_homestory_N23paixi_90040107_15_dialog_content = "Quero dizer, você realmente me ajudou.",
  str_homestory_N23paixi_90040107_16_dialog_content = "Eu vejo. Tudo bem então.",
  str_homestory_N23paixi_90040107_17_dialog_content = "Levarei sua gratidão a sério.",
  str_homestory_N23paixi_90040107_18_dialog_content = "É disso que estou falando!",
  str_homestory_N23paixi_90040108_1_dialog_content = "Vice!",
  str_homestory_N23paixi_90040108_2_dialog_content = "Waaaah! Eu estou tão feliz! Eu vejo isso, PlayerName!",
  str_homestory_N23paixi_90040108_3_dialog_content = "Eu não posso acreditar que você já montou o estúdio de cinema!",
  str_homestory_N23paixi_90040108_4_dialog_content = "Ahaha. Mesmo que eu esteja feliz por ser elogiado por você...",
  str_homestory_N23paixi_90040108_5_dialog_content = "Minos realmente fez a maior parte do trabalho aqui.",
  str_homestory_N23paixi_90040108_6_dialog_content = "Tudo o que fiz foi reunir materiais para ele.",
  str_homestory_N23paixi_90040108_7_dialog_content = "Oh, eu vejo...",
  str_homestory_N23paixi_90040108_8_dialog_content = "Você acha que há algo no mundo que Minos não pode fazer?",
  str_homestory_N23paixi_90040108_9_dialog_content = "Na verdade, estou curioso sobre isso também.",
  str_homestory_N23paixi_90040108_10_dialog_content = "De qualquer forma, eu lhe agradeci muito.",
  str_homestory_N23paixi_90040108_11_dialog_content = "Ótimo.",
  str_homestory_N23paixi_90040108_12_dialog_content = "Agora que o estúdio de cinema está pronto para ir, vamos experimentá-lo!",
  str_homestory_N23paixi_90040108_13_dialog_content = "Você leu minha mente!",
  str_homestory_N23paixi_90040108_14_dialog_content = "Ah, e Minos me deu um <color=#FFB400>roteiro</color>.",
  str_homestory_N23paixi_90040108_15_dialog_content = "Agora vamos dar a esta coisa um bom estudo, não é?",
  str_homestory_N23paixi_90040108_16_dialog_content = "Heheh. O pensamento de estudar novas máquinas me enche de emoção!",
  str_homestory_N23paixi_90040108_17_dialog_content = "Não são apenas máquinas, Vice... Isso é uma forma de arte.",
  str_homestory_N23paixi_90040108_18_dialog_content = "Eu sei!",
  str_homestory_N23paixi_90040201_1_dialog_content = "Ei, PlayerName!",
  str_homestory_N23paixi_90040201_2_dialog_content = "Oi, Lilica!",
  str_homestory_N23paixi_90040201_3_dialog_content = "Uau! Eu realmente tenho que dizer—",
  str_homestory_N23paixi_90040201_4_dialog_content = "Cloud Gardens é muuuuito impressionante!",
  str_homestory_N23paixi_90040201_5_dialog_content = "Eu nunca teria pensado que haveria um estúdio de cinema aqui!",
  str_homestory_N23paixi_90040201_6_dialog_content = "Não só isso, mas todo o equipamento parece tão profissional também!",
  str_homestory_N23paixi_90040201_7_dialog_content = "Você realmente é super atencioso, como todo mundo diz!",
  str_homestory_N23paixi_90040201_8_dialog_content = "Não sei como agradecer por cuidar das necessidades de cinéfilos como eu! Você é incrível!",
  str_homestory_N23paixi_90040201_9_dialog_content = "E-Espere um minuto, Lilica.",
  str_homestory_N23paixi_90040201_10_dialog_content = "Minos realmente forneceu a maioria das coisas que você vê no estúdio.",
  str_homestory_N23paixi_90040201_11_dialog_content = "Huh? Dele?",
  str_homestory_N23paixi_90040201_12_dialog_content = "Certo. Isso explica muito.",
  str_homestory_N23paixi_90040201_13_dialog_content = "Quer dizer, só alguém com experiência relevante poderia fazer um estúdio como esse.",
  str_homestory_N23paixi_90040201_14_dialog_content = "Sim. Pessoalmente, não acho que fazer filmes seja uma coisa simples.",
  str_homestory_N23paixi_90040201_15_dialog_content = "Basta olhar para lá...",
  str_homestory_N23paixi_90040201_16_dialog_content = "Os cenários e os cenários estão prontos.",
  str_homestory_N23paixi_90040201_17_dialog_content = "Mas ainda não sei exatamente como operar a câmera ou encontrar os atores certos para o trabalho.<sprite=emo_tanqi size=60 />",
  str_homestory_N23paixi_90040201_18_dialog_content = "Hum, é mesmo?",
  str_homestory_N23paixi_90040201_19_dialog_content = "Bem, não se preocupe, PlayerName. Eu posso cuidar de encontrar os atores certos para você.",
  str_homestory_N23paixi_90040201_20_dialog_content = "Sobre a câmera e outras coisas... mesmo que eu tenha alguma experiência com eles, ainda sou praticamente um novato.",
  str_homestory_N23paixi_90040201_21_dialog_content = "PlayerName, por que você não pergunta para aquela garota bonita que sempre está com o nariz enfiado em um livro?",
  str_homestory_N23paixi_90040201_22_dialog_content = "Não estou aqui há muito tempo, mas toda vez que a vejo...",
  str_homestory_N23paixi_90040201_23_dialog_content = "Quero dizer TODA VEZ, ela está sempre lendo.",
  str_homestory_N23paixi_90040201_24_dialog_content = "A garota de quem você está falando... tem cabelos castanhos compridos e encaracolados, certo?",
  str_homestory_N23paixi_90040201_25_dialog_content = "Sim!",
  str_homestory_N23paixi_90040201_26_dialog_content = "Ela parece muito inteligente!",
  str_homestory_N23paixi_90040201_27_dialog_content = "Bem, não poderia ser mais ninguém.",
  str_homestory_N23paixi_90040201_28_dialog_content = "Acho que vou falar com <color=#FFB400>Hedy</color> agora, então.",
  str_homestory_N23paixi_90040201_29_dialog_content = "Então o nome dela é Hedy?",
  str_homestory_N23paixi_90040201_30_dialog_content = "Eu sabia. Garotas bonitas também têm nomes bonitos.",
  str_homestory_N23paixi_90040201_31_dialog_content = "Vou esperar por suas boas notícias, então, PlayerName!",
  str_homestory_N23paixi_90040202_1_dialog_content = "Hum? É você.",
  str_homestory_N23paixi_90040202_2_dialog_content = "Oi.",
  str_homestory_N23paixi_90040202_3_dialog_content = "Oi, Hedy!",
  str_homestory_N23paixi_90040202_4_dialog_content = "O que está fazendo?",
  str_homestory_N23paixi_90040202_5_dialog_content = "Leitura.",
  str_homestory_N23paixi_90040202_6_dialog_content = "Ah sim, você parece fazer muito isso.",
  str_homestory_N23paixi_90040202_7_dialog_content = "Mas você escolheu ler aqui hoje em vez de ler no seu quarto.",
  str_homestory_N23paixi_90040202_8_dialog_content = "Você está tentando perguntar por que estou lendo aqui?",
  str_homestory_N23paixi_90040202_9_dialog_content = "Você é um observador perspicaz, eu vou lhe dar isso.",
  str_homestory_N23paixi_90040202_10_dialog_content = "Para ser honesto, tenho lido livros sobre peixes recentemente.",
  str_homestory_N23paixi_90040202_11_dialog_content = "Eu queria investigar um <color=#FFB400>Cobra</color> em pessoa...",
  str_homestory_N23paixi_90040202_12_dialog_content = "Mas não sei onde você guarda seu equipamento de pesca.",
  str_homestory_N23paixi_90040202_13_dialog_content = "Então pensei em dar uma olhada por aí...",
  str_homestory_N23paixi_90040202_14_dialog_content = "Equipamento de pesca? Você poderia ter me perguntado.",
  str_homestory_N23paixi_90040202_15_dialog_content = "Por que eu pediria a alguém para me ajudar com algo tão insignificante?",
  str_homestory_N23paixi_90040202_16_dialog_content = "Hum... tudo bem.",
  str_homestory_N23paixi_90040202_17_dialog_content = "Na verdade, podemos pular tudo isso.",
  str_homestory_N23paixi_90040202_18_dialog_content = "Por que eu não pego um Snakeel para você estudar? Quero dizer, se você quiser, é isso.",
  str_homestory_N23paixi_90040202_19_dialog_content = "Eu não poderia incomodá-lo assim...",
  str_homestory_N23paixi_90040202_20_dialog_content = "Não se preocupe, porque também tenho algo que preciso perguntar a você.",
  str_homestory_N23paixi_90040202_21_dialog_content = "Ah?",
  str_homestory_N23paixi_90040202_22_dialog_content = "... Entendo.",
  str_homestory_N23paixi_90040202_23_dialog_content = "Eu realmente tenho alguns livros sobre cinema.",
  str_homestory_N23paixi_90040202_24_dialog_content = "Eu vou buscá-los para você em um pouco, se você precisar deles.",
  str_homestory_N23paixi_90040202_25_dialog_content = "Na verdade... eu vou para o meu quarto e vou buscá-los para você agora mesmo.",
  str_homestory_N23paixi_90040202_26_dialog_content = "Seria ótimo! Obrigado, Hedy!",
  str_homestory_N23paixi_90040202_27_dialog_content = "O prazer é meu.",
  str_homestory_N23paixi_90040202_28_dialog_content = "Vamos nos encontrar aqui e negociar, então.",
  str_homestory_N23paixi_90040202_29_dialog_content = "Pode deixar!",
  str_homestory_N23paixi_90040203_1_dialog_content = "Você já tem três Snakeels?",
  str_homestory_N23paixi_90040203_2_dialog_content = "Entendi! ({1}/{2})",
  str_homestory_N23paixi_90040203_5_dialog_content = "Obrigado.",
  str_homestory_N23paixi_90040203_3_dialog_content = "Ainda estou trabalhando nisso!",
  str_homestory_N23paixi_90040203_4_dialog_content = "Eu te desejo sorte.",
  str_homestory_N23paixi_90040204_1_dialog_content = "Aqui estão os livros que você queria.",
  str_homestory_N23paixi_90040204_2_dialog_content = "Folheei-os brevemente. O que eu mais recomendo é <color=#FFB400>30 lições sobre como administrar um estúdio de cinema</color>.",
  str_homestory_N23paixi_90040204_3_dialog_content = "Ele não apenas discute teorias, mas também ensina como aplicá-las usando exemplos reais.",
  str_homestory_N23paixi_90040204_4_dialog_content = "O autor costumava trabalhar como membro da equipe de filmagem, então eles também ofereceram soluções para muitos problemas comuns.",
  str_homestory_N23paixi_90040204_5_dialog_content = "No geral, acho que este livro vai realmente ajudá-lo.",
  str_homestory_N23paixi_90040204_6_dialog_content = "Eu vejo! Você é muito atencioso, Hedy.",
  str_homestory_N23paixi_90040204_7_dialog_content = "Com certeza estudarei cuidadosamente cada palavra deste livro!",
  str_homestory_N23paixi_90040204_8_dialog_content = "Ahem, c-como você lê o livro não tem nada a ver comigo!<sprite=emo_baimao size=60 />",
  str_homestory_N23paixi_90040204_9_dialog_content = "De qualquer forma, muito obrigado!",
  str_homestory_N23paixi_90040204_10_dialog_content = "O prazer é meu.",
  str_homestory_N23paixi_90040205_1_dialog_content = "Uau! 30 lições sobre como administrar um estúdio de cinema!?",
  str_homestory_N23paixi_90040205_2_dialog_content = "Uaaau! Você e Hedy são maravilhosos!",
  str_homestory_N23paixi_90040205_3_dialog_content = "Parece uma ótima leitura!",
  str_homestory_N23paixi_90040205_4_dialog_content = "Especialmente para mim!",
  str_homestory_N23paixi_90040205_5_dialog_content = "Agora que temos este livro, se eu não conseguir me tornar um ator de verdade no futuro, pelo menos ainda posso trabalhar entre a equipe!",
  str_homestory_N23paixi_90040205_6_dialog_content = "Uau Lilica, isso é muito... pragmático da sua parte!",
  str_homestory_N23paixi_90040205_7_dialog_content = "É claro! Foi assim que cheguei onde estou hoje.",
  str_homestory_N23paixi_90040205_8_dialog_content = "Tudo bem. Agora temos tudo o que precisamos para fazer um filme...",
  str_homestory_N23paixi_90040205_9_dialog_content = "e também nosso primeiro roteiro, além de um livro cheio de soluções para situações de emergência!",
  str_homestory_N23paixi_90040205_10_dialog_content = "Certo. Então podemos começar a fazer filmes, certo?",
  str_homestory_N23paixi_90040205_11_dialog_content = "Dê-me tempo para ler este livro primeiro!",
  str_homestory_N23paixi_90040205_12_dialog_content = "Ainda tenho que aprender a operar o equipamento!",
  str_homestory_N23paixi_90040205_13_dialog_content = "Certo. Vou ler com você, então.",
  str_homestory_N23paixi_90040301_1_dialog_content = "Heheh, PlayerName! Eu tenho boas notícias para você.",
  str_homestory_N23paixi_90040301_2_dialog_content = "Nosso estúdio de cinema está em pleno funcionamento!",
  str_homestory_N23paixi_90040301_3_dialog_content = "Você conhece todos os equipamentos que a gente vasculhava tanto? Eles não estão quebrados!",
  str_homestory_N23paixi_90040301_4_dialog_content = "Não só isso, eu já fiz alguns shorts com eles!",
  str_homestory_N23paixi_90040301_5_dialog_content = "O equipamento realmente é de boa qualidade, heheh.<sprite=emo_guilian size=60 />",
  str_homestory_N23paixi_90040301_6_dialog_content = "Ahahaha... Sobre isso... Acho que às vezes precisamos ser mais gentis com o equipamento.",
  str_homestory_N23paixi_90040301_7_dialog_content = "Sim, você tem razão.",
  str_homestory_N23paixi_90040301_8_dialog_content = "Mas estou aqui para falar de negócios com você.",
  str_homestory_N23paixi_90040301_9_dialog_content = "Muitos aurorianos viram o estúdio.",
  str_homestory_N23paixi_90040301_10_dialog_content = "Eles me disseram que também querem fazer seus próprios filmes e tentar fazer suas próprias ideias ganharem vida.",
  str_homestory_N23paixi_90040301_11_dialog_content = "Mas como não sou o chefe aqui, achei que deveria pedir sua opinião.",
  str_homestory_N23paixi_90040301_12_dialog_content = "É claro. Sem problemas.",
  str_homestory_N23paixi_90040301_13_dialog_content = "Sim! Eu sabia que você diria tudo bem!",
  str_homestory_N23paixi_90040301_14_dialog_content = "Mas, Lilica...",
  str_homestory_N23paixi_90040301_15_dialog_content = "Se esperarmos até que todos tenham a chance de se familiarizar com o equipamento antes de começarmos a fazer filmes... Não seria perder muito tempo?",
  str_homestory_N23paixi_90040301_16_dialog_content = "Hehehe, não se preocupe.",
  str_homestory_N23paixi_90040301_17_dialog_content = "Quem está empunhando a câmera não será outro senão você mesmo, Lilica, a diretora em ascensão!",
  str_homestory_N23paixi_90040301_18_dialog_content = "Ao ajudar todos a realizar seus desejos de fazer seus próprios filmes, também poderei obter muita experiência prática de filmagem!",
  str_homestory_N23paixi_90040301_19_dialog_content = "É uma situação ganha-ganha de qualquer maneira que você olhe para isso.",
  str_homestory_N23paixi_90040301_20_dialog_content = "Portanto, não se preocupe com os problemas técnicos!",
  str_homestory_N23paixi_90040301_21_dialog_content = "Então tá.",
  str_homestory_N23paixi_90040301_22_dialog_content = "Confio no seu profissionalismo, Lilica.",
  str_homestory_N23paixi_90040301_23_dialog_content = "Muito bom!",
  str_homestory_N23paixi_90040301_24_dialog_content = "Agora, devemos ir e começar a ajudar nosso primeiro cliente!",
  str_homestory_N23paixi_90040301_25_dialog_content = "Nosso primeiro cliente?",
  str_homestory_N23paixi_90040301_26_dialog_content = "Exatamente!",
  str_homestory_N23paixi_90040301_27_dialog_content = "Sadie está esperando por você em <color=#FFB400>Praça Jacinto</color>!",
  str_homestory_N23paixi_90040301_28_dialog_content = "Huh? Por que eu?",
  str_homestory_N23paixi_90040301_29_dialog_content = "Porque eu tenho que ficar aqui e me familiarizar com o equipamento!",
  str_homestory_N23paixi_90040301_30_dialog_content = "E você conhece todos aqui mais do que eu, não é?",
  str_homestory_N23paixi_90040301_31_dialog_content = "Certo... Certo. Vejo você mais tarde, então.",
  str_homestory_N23paixi_90040301_32_dialog_content = "Estarei esperando aqui.",
  str_homestory_N23paixi_90040302_1_dialog_content = "Você está finalmente aqui, PlayerName. Eu tenho antecipado você.",
  str_homestory_N23paixi_90040302_2_dialog_content = "Oi, Sadi!",
  str_homestory_N23paixi_90040302_3_dialog_content = "Lilica me disse que você quer fazer um filme sobre espadachins, certo?",
  str_homestory_N23paixi_90040302_4_dialog_content = "Exatamente!",
  str_homestory_N23paixi_90040302_5_dialog_content = "Tenho ideias, mas nenhum plano concreto.",
  str_homestory_N23paixi_90040302_6_dialog_content = "Há muitas garotas legais aqui, mas eu não sou uma delas.",
  str_homestory_N23paixi_90040302_7_dialog_content = "Mas isso não muda o fato de que eu quero fazer um filme de espadachim de verdade!",
  str_homestory_N23paixi_90040302_8_dialog_content = "Uhm... Por que você não me conta sobre sua ideia primeiro?",
  str_homestory_N23paixi_90040302_9_dialog_content = "Então vamos ver se podemos fazer isso acontecer.",
  str_homestory_N23paixi_90040302_10_dialog_content = "Primeiro, quero que aconteça à noite. Uma noite muito escura.",
  str_homestory_N23paixi_90040302_11_dialog_content = "Segundo, quero que haja muitos inimigos em guarda.",
  str_homestory_N23paixi_90040302_12_dialog_content = "Terceiro, quero que você pergunte às garotas legais algo para mim.",
  str_homestory_N23paixi_90040302_13_dialog_content = "Toda vez que tento perguntar a eles, eles entram em pânico e se escondem.",
  str_homestory_N23paixi_90040302_14_dialog_content = "É como se eles estivessem preocupados que eu seja perigoso e que eu os sequestre ou algo assim.",
  str_homestory_N23paixi_90040302_15_dialog_content = "Uhm... Então, quem você quer que eu pergunte?",
  str_homestory_N23paixi_90040302_16_dialog_content = "Allura! Allura!",
  str_homestory_N23paixi_90040302_17_dialog_content = "Tá bom.",
  str_homestory_N23paixi_90040302_18_dialog_content = "Você só quer que eu pergunte a ela como é um dia em sua vida como um mercenário maduro e legal, certo?",
  str_homestory_N23paixi_90040302_19_dialog_content = "Sim Sim Sim!",
  str_homestory_N23paixi_90040302_20_dialog_content = "Você fica aqui. Eu volto já.",
  str_homestory_N23paixi_90040302_21_dialog_content = "Você é demais.<sprite=emo_dianzan size=60 />",
  str_homestory_N23paixi_90040303_1_dialog_content = "Você precisava de algo?",
  str_homestory_N23paixi_90040303_2_dialog_content = "Ah, hum... Aham!",
  str_homestory_N23paixi_90040303_3_dialog_content = "Eu só queria saber como você estava se adaptando, Allura.",
  str_homestory_N23paixi_90040303_4_dialog_content = "Contanto que eu possa aceitar empregos, onde eu moro realmente não importa.",
  str_homestory_N23paixi_90040303_5_dialog_content = "Certo! Empregos!",
  str_homestory_N23paixi_90040303_6_dialog_content = "Um...?",
  str_homestory_N23paixi_90040303_7_dialog_content = "Certo. Então, como é o seu dia como um mercenário maduro e legal?",
  str_homestory_N23paixi_90040303_8_dialog_content = "Você está tentando me fazer fazer algo para você de graça?",
  str_homestory_N23paixi_90040303_9_dialog_content = "É por isso que você está tentando me lisonjear?",
  str_homestory_N23paixi_90040303_10_dialog_content = "Não! Eu só estou curioso. Isso é tudo! Hahah.",
  str_homestory_N23paixi_90040303_11_dialog_content = "Depende do trabalho.",
  str_homestory_N23paixi_90040303_12_dialog_content = "Se for um trabalho de alto risco, então faço minha lição de casa e reúno todas as informações que posso antes de começar.",
  str_homestory_N23paixi_90040303_13_dialog_content = "Quanto aos trabalhos comuns, tento concluí-los o mais rápido que posso para poder passar para outro.",
  str_homestory_N23paixi_90040303_14_dialog_content = "Posso dizer com certeza que a experiência acumulada em todos esses pequenos trabalhos diários é crucial para o sucesso dos trabalhos de maior risco.",
  str_homestory_N23paixi_90040303_15_dialog_content = "Eles treinam você em pontaria e combate físico, e também o preparam para manter um bom relacionamento com seus clientes.",
  str_homestory_N23paixi_90040303_16_dialog_content = "Direita!",
  str_homestory_N23paixi_90040303_17_dialog_content = "Reúna... informações... concluindo trabalhos com pressa...",
  str_homestory_N23paixi_90040303_18_dialog_content = "OK. Eu entendi. Obrigado, Allura!",
  str_homestory_N23paixi_90040303_19_dialog_content = "Muito obrigado por compartilhar!",
  str_homestory_N23paixi_90040303_20_dialog_content = "Obrigado por me agradecer.",
  str_homestory_N23paixi_90040303_21_dialog_content = "Agora, pague.",
  str_homestory_N23paixi_90040303_22_dialog_content = "Eu sabia!",
  str_homestory_N23paixi_90040304_1_dialog_content = "Treinamento diário, sem procrastinação, coleta de informações e análise de trabalho!",
  str_homestory_N23paixi_90040304_2_dialog_content = "Um ataque completo na escuridão da noite!",
  str_homestory_N23paixi_90040304_3_dialog_content = "Obrigado, PlayerName!",
  str_homestory_N23paixi_90040304_4_dialog_content = "Agora sei que tipo de filme quero fazer.",
  str_homestory_N23paixi_90040304_5_dialog_content = "Eu só preciso adicionar mais algumas coisas para deixar meu script perfeito!",
  str_homestory_N23paixi_90040304_6_dialog_content = "Você receberá meu roteiro completo em breve!",
  str_homestory_N23paixi_90040304_7_dialog_content = "Muito obrigadooooooo! Obrigado, obrigado, obrigado, obrigado!",
  str_homestory_N23paixi_90040304_8_dialog_content = "Tudo bem, tudo bem. Você não precisa dizer isso tantas vezes.",
  str_homestory_N23paixi_90040304_9_dialog_content = "Hehehe.",
  str_homestory_N23paixi_90040304_10_dialog_content = "Você é demais, PlayerName!<sprite=emo_dianzan size=60 />",
  str_homestory_N23paixi_90040305_1_dialog_content = "Então, como foi? Você recebeu uma resposta?",
  str_homestory_N23paixi_90040305_2_dialog_content = "Sim. Agora eu sei como um mercenário legal supostamente passa o dia.",
  str_homestory_N23paixi_90040305_3_dialog_content = "Heehe, que ótimo.",
  str_homestory_N23paixi_90040305_4_dialog_content = "Agora nosso roteiro ficará ainda melhor!",
  str_homestory_N23paixi_90040305_5_dialog_content = "Não apenas obtivemos uma ótima resposta, mas também podemos dar ao filme um toque especial de Sadie!",
  str_homestory_N23paixi_90040305_6_dialog_content = "Eu acho que você poderia colocar dessa forma, mas eu me pergunto como o filme baseado nesse roteiro vai acabar...",
  str_homestory_N23paixi_90040305_7_dialog_content = "Não posso deixar de me sentir preocupado.",
  str_homestory_N23paixi_90040305_8_dialog_content = "Bem, é assim que eu penso em coisas assim.",
  str_homestory_N23paixi_90040305_9_dialog_content = "Claro, somos todos novatos aqui, mas todos os \"profissionais\" também já foram novatos. Eles chegaram onde estão agora aprendendo ao longo do caminho, certo?",
  str_homestory_N23paixi_90040305_10_dialog_content = "E daí se esse filme ficar ruim? Aprenderemos com nossos erros e seremos melhores da próxima vez!",
  str_homestory_N23paixi_90040305_11_dialog_content = "Tens razão, Lilica! Agora me sinto animado!",
  str_homestory_N23paixi_90040305_12_dialog_content = "Então, vamos nos mexer!",
  str_homestory_N23paixi_90040305_13_dialog_content = "Sim!",
  str_homestory_N23paixi_90040401_1_dialog_content = "PlayerName...",
  str_homestory_N23paixi_90040401_2_dialog_content = "O que há de errado, Lilica?",
  str_homestory_N23paixi_90040401_3_dialog_content = "Você parece um pouco chateado.",
  str_homestory_N23paixi_90040401_4_dialog_content = "Estou preocupado com os adereços que vamos precisar para o filme.",
  str_homestory_N23paixi_90040401_5_dialog_content = "Você quer dizer os adereços para \"The Swashbuckler\"?",
  str_homestory_N23paixi_90040401_6_dialog_content = "Exatamente!",
  str_homestory_N23paixi_90040401_7_dialog_content = "Sadie exigiu que essa cena fosse \"comovente\", então todo o orçamento vai para isso!",
  str_homestory_N23paixi_90040401_8_dialog_content = "Mas a julgar pela qualidade dos adereços que temos...",
  str_homestory_N23paixi_90040401_9_dialog_content = "Eles não estão à altura dos padrões dela, estão?",
  str_homestory_N23paixi_90040401_10_dialog_content = "Não apenas seus padrões. Eles nem conhecem os meus.",
  str_homestory_N23paixi_90040401_11_dialog_content = "Devo... perguntar a ela sobre isso?",
  str_homestory_N23paixi_90040401_12_dialog_content = "Quero dizer, a maioria de suas demandas tendem a ser abstratas e não concretas.<sprite=emo_baiyan size=60 />",
  str_homestory_N23paixi_90040401_13_dialog_content = "Isso seria bom!",
  str_homestory_N23paixi_90040401_14_dialog_content = "Agradeço antecipadamente, PlayerName.",
  str_homestory_N23paixi_90040401_15_dialog_content = "Certo!",
  str_homestory_N23paixi_90040402_1_dialog_content = "Ah...",
  str_homestory_N23paixi_90040402_2_dialog_content = "Então, você só precisa que eu diga exatamente quais adereços eu tenho em mente?",
  str_homestory_N23paixi_90040402_3_dialog_content = "Sim. Tente ser detalhado e específico.",
  str_homestory_N23paixi_90040402_4_dialog_content = "Nesta cena, o espadachim olha para um <color=#FFB400>espelho</color> e expressa suas preocupações e dificuldades.",
  str_homestory_N23paixi_90040402_5_dialog_content = "E então vem o clímax do filme – o swashbuckler se transforma!<sprite=emo_nuhuo size=60 />",
  str_homestory_N23paixi_90040402_6_dialog_content = "O espelho de repente emite uma luz radiante de arco-íris e estrelas douradas brilhantes e corações cor-de-rosa aparecem ao seu redor!",
  str_homestory_N23paixi_90040402_7_dialog_content = "É melhor se pudermos girar a câmera 360 graus ao redor do espadachim, com um close do espadachim para mostrar que ela está crescida!",
  str_homestory_N23paixi_90040402_8_dialog_content = "Yeah, yeah! E assim que ela decide o que fazer, ela consegue esse misterioso poder mágico que a transforma em uma mulher linda e forte!",
  str_homestory_N23paixi_90040402_9_dialog_content = "... Não é isso que eles chamam de transformação de garota mágica? O tipo de coisa que só acontece em quadrinhos de fantasia infantil?",
  str_homestory_N23paixi_90040402_10_dialog_content = "T-Isso não serve?",
  str_homestory_N23paixi_90040402_11_dialog_content = "Eu... quero dizer, não é desfazível.",
  str_homestory_N23paixi_90040402_12_dialog_content = "Enfim, tudo que você precisa é aquele espelho com poderes mágicos, certo?",
  str_homestory_N23paixi_90040402_13_dialog_content = "Isso mesmo.",
  str_homestory_N23paixi_90040402_14_dialog_content = "Bem, nesse caso... provavelmente podemos fazer a moldura do espelho de madeira.",
  str_homestory_N23paixi_90040402_15_dialog_content = "Sim!",
  str_homestory_N23paixi_90040402_16_dialog_content = "Hum, tudo bem.",
  str_homestory_N23paixi_90040402_17_dialog_content = "De qualquer forma, eu vou <color=#FFB400>junte um pouco de madeira</color> primeiro...",
  str_homestory_N23paixi_90040402_18_dialog_content = "Fazer a moldura de um espelho parece ser bastante fácil.",
  str_homestory_N23paixi_90040402_19_dialog_content = "Sim!",
  str_homestory_N23paixi_90040402_20_dialog_content = "Ah, eu não deveria ter dito isso.",
  str_homestory_N23paixi_90040402_21_dialog_content = "Devo dizer: obrigado, PlayerName!",
  str_homestory_N23paixi_90040402_22_dialog_content = "Apenas me traga a madeira. Eu mesmo posso fazer o quadro!",
  str_homestory_N23paixi_90040402_23_dialog_content = "Tá bom.",
  str_homestory_N23paixi_90040403_1_dialog_content = "Você é tão rápido, PlayerName.",
  str_homestory_N23paixi_90040403_2_dialog_content = "Tudo feito. ({1}/{2})",
  str_homestory_N23paixi_90040403_5_dialog_content = "Uau! Você é tão legal, PlayerName!",
  str_homestory_N23paixi_90040403_6_dialog_content = "Você pode realmente fazer o espelho de madeira?",
  str_homestory_N23paixi_90040403_7_dialog_content = "Você precisa da minha ajuda?",
  str_homestory_N23paixi_90040403_8_dialog_content = "Tenha alguma fé em mim. Eu posso fazer isso.",
  str_homestory_N23paixi_90040403_9_dialog_content = "Acho que vamos precisar de algum minério.",
  str_homestory_N23paixi_90040403_10_dialog_content = "Certo... Você só pode fazer a estrutura básica de madeira.",
  str_homestory_N23paixi_90040403_11_dialog_content = "Nós vamos precisar <color=#FFB400>minério</color> para fazer o espelho real.",
  str_homestory_N23paixi_90040403_12_dialog_content = "Bingo!",
  str_homestory_N23paixi_90040403_13_dialog_content = "Tudo bem. eu irei <color=#FFB400>recolher algum minério</color>, então.",
  str_homestory_N23paixi_90040403_14_dialog_content = "Não há necessidade de se esforçar, você ouviu? Podemos fazer o espelho juntos quando eu voltar.",
  str_homestory_N23paixi_90040403_15_dialog_content = "Saquei!",
  str_homestory_N23paixi_90040403_3_dialog_content = "Só um pouco mais.",
  str_homestory_N23paixi_90040403_4_dialog_content = "Eu estarei esperando!",
  str_homestory_N23paixi_90040404_1_dialog_content = "Você é tão rápido, PlayerName.",
  str_homestory_N23paixi_90040404_2_dialog_content = "Tudo feito. ({1}/{2})",
  str_homestory_N23paixi_90040404_5_dialog_content = "Uau! Você é tão legal, PlayerName!",
  str_homestory_N23paixi_90040404_6_dialog_content = "Agora temos tudo o que precisamos. Eu estou feliz.",
  str_homestory_N23paixi_90040404_7_dialog_content = "Me dê um tempo, PlayerName. Com certeza vou deslumbrá-lo com meu trabalho.",
  str_homestory_N23paixi_90040404_8_dialog_content = "Você realmente não precisa da minha ajuda?",
  str_homestory_N23paixi_90040404_9_dialog_content = "Vocę... realmente sabe fazer um espelho?",
  str_homestory_N23paixi_90040404_10_dialog_content = "Já fiz um trabalho assim. Tive que arrancar 31 espelhos.<sprite=emo_mojing size=60 />",
  str_homestory_N23paixi_90040404_11_dialog_content = "Eu posso fazer isso!",
  str_homestory_N23paixi_90040404_12_dialog_content = "Tudo bem... Se você insiste.",
  str_homestory_N23paixi_90040404_13_dialog_content = "Vai embora, PlayerName! Deixe-me com meu trabalho!",
  str_homestory_N23paixi_90040404_14_dialog_content = "Tá bom...",
  str_homestory_N23paixi_90040404_3_dialog_content = "Só um pouco mais.",
  str_homestory_N23paixi_90040404_4_dialog_content = "Eu estarei esperando!",
  str_homestory_N23paixi_90040405_1_dialog_content = "Heheh. PlayerName!",
  str_homestory_N23paixi_90040405_2_dialog_content = "Oi, Sadi!",
  str_homestory_N23paixi_90040405_3_dialog_content = "Como vão as coisas?",
  str_homestory_N23paixi_90040405_4_dialog_content = "Não se preocupe. Eu só queria ver se você precisava de uma mão.",
  str_homestory_N23paixi_90040405_5_dialog_content = "Já terminei de fazer o espelho mágico!",
  str_homestory_N23paixi_90040405_6_dialog_content = "Você vai ver daqui a pouco.",
  str_homestory_N23paixi_90040405_7_dialog_content = "Sério? Então onde está?",
  str_homestory_N23paixi_90040405_8_dialog_content = "Está no meu quarto. Eu tenho que polir antes de poder mostrar para você.",
  str_homestory_N23paixi_90040405_9_dialog_content = "Tudo que você precisa fazer é esperar!",
  str_homestory_N23paixi_90040405_10_dialog_content = "Sério? Você é mais capaz do que eu imaginava, Sadie.",
  str_homestory_N23paixi_90040405_11_dialog_content = "Ei!",
  str_homestory_N23paixi_90040405_12_dialog_content = "Ahem, quero dizer, você realmente é capaz!",
  str_homestory_N23paixi_90040405_13_dialog_content = "Isso é melhor.",
  str_homestory_N23paixi_90040406_1_dialog_content = "Oláoooooo PlayerName!",
  str_homestory_N23paixi_90040406_2_dialog_content = "Você conseguiu o suporte? Você fez você fez você?",
  str_homestory_N23paixi_90040406_3_dialog_content = "Consegui, consegui.",
  str_homestory_N23paixi_90040406_4_dialog_content = "Então, qual era o adereço que Sadie tinha em mente para a cena \"tocante\"?",
  str_homestory_N23paixi_90040406_5_dialog_content = "Eu sou tão curioso!",
  str_homestory_N23paixi_90040406_6_dialog_content = "Acontece que o que ela continuou falando era um espelho.",
  str_homestory_N23paixi_90040406_7_dialog_content = "Um espelho?",
  str_homestory_N23paixi_90040406_8_dialog_content = "Sim. Francamente, não consigo me imaginar filmando a cena que ela tem em mente, mas...",
  str_homestory_N23paixi_90040406_9_dialog_content = "Como você disse, não faria mal tentar.",
  str_homestory_N23paixi_90040406_10_dialog_content = "Sim!",
  str_homestory_N23paixi_90040406_11_dialog_content = "Então você está pronto?",
  str_homestory_N23paixi_90040406_12_dialog_content = "Podemos começar a filmar o primeiro filme do nosso estúdio!",
  str_homestory_N23paixi_90040406_13_dialog_content = "Sim, estou pronto!",
  str_homestory_N23paixi_90040406_14_dialog_content = "Tudo bem! Então...",
  str_homestory_N23paixi_90040406_15_dialog_content = "Agora que temos nosso set, adereços e equipamentos...",
  str_homestory_N23paixi_90040406_16_dialog_content = "Vamos compensar tudo o que nos falta com a nossa paixão!",
  str_homestory_N23paixi_90040406_17_dialog_content = "E agora, vamos colocar nossa protagonista feminina em cena! Sadie, a espadachim!",
  str_homestory_N23paixi_90040406_18_dialog_content = "Preparar! Todos em posição?",
  str_homestory_N23paixi_90040406_19_dialog_content = "Espera.",
  str_homestory_N23paixi_90040406_20_dialog_content = "Agora, ação!<sprite=emo_laba size=60 />",
  str_homestory_N23paixi_90040406_21_dialog_content = "A história...",
  str_homestory_N23paixi_90040406_22_dialog_content = "começa em uma noite fria e escura como breu...",
  str_homestory_N23paixi_90040501_1_dialog_content = "PlayerName! Bom momento! Eu tenho uma coisa que eu queria te perguntar!",
  str_homestory_N23paixi_90040501_2_dialog_content = "O que foi?",
  str_homestory_N23paixi_90040501_3_dialog_content = "Você sabe como acabamos de filmar The Swashbuckler?",
  str_homestory_N23paixi_90040501_4_dialog_content = "Aconteceu alguma coisa? Mas já terminamos de filmar...",
  str_homestory_N23paixi_90040501_5_dialog_content = "Oh! De jeito nenhum. O filme está feito. Não é sobre isso!",
  str_homestory_N23paixi_90040501_6_dialog_content = "Ufa, isso é um alívio.",
  str_homestory_N23paixi_90040501_7_dialog_content = "Há esta menina mais velha. Quero dizer, ela não é TÃO velha, mas pelo menos mais velha que eu.",
  str_homestory_N23paixi_90040501_8_dialog_content = "Ela tem andado pelo estúdio ultimamente.",
  str_homestory_N23paixi_90040501_9_dialog_content = "Mas sempre que quero me aproximar dela e perguntar se ela quer fazer um filme,",
  str_homestory_N23paixi_90040501_10_dialog_content = "Eu sinto essa aura arrepiante emitida por ela e isso me assusta.",
  str_homestory_N23paixi_90040501_11_dialog_content = "Ver! Lá está ela!",
  str_homestory_N23paixi_90040501_12_dialog_content = "Oh isso é <color=#FFB400>Paloma</color>.",
  str_homestory_N23paixi_90040501_13_dialog_content = "Paloma. De alguma forma, esse nome soa familiar.<sprite=emo_yaosu size=60 />",
  str_homestory_N23paixi_90040501_14_dialog_content = "Bem, talvez seja porque ela também morou em Umbraton por um tempo?",
  str_homestory_N23paixi_90040501_15_dialog_content = "Mas muitas pessoas vivem em Umbraton.",
  str_homestory_N23paixi_90040501_16_dialog_content = "Haha, acho que você está certo.",
  str_homestory_N23paixi_90040501_17_dialog_content = "Hmph! Você está apenas dizendo o que quer, não é, PlayerName?",
  str_homestory_N23paixi_90040501_18_dialog_content = "Por que você não vai lá e pergunta a ela por que ela está andando pelo estúdio!",
  str_homestory_N23paixi_90040501_19_dialog_content = "Meus instintos me dizem que ela quer fazer um filme, mas não sabe como nos dizer.",
  str_homestory_N23paixi_90040501_20_dialog_content = "Hum, vou descobrir.",
  str_homestory_N23paixi_90040502_1_dialog_content = "PlayerName.",
  str_homestory_N23paixi_90040502_2_dialog_content = "Oi, Paloma.",
  str_homestory_N23paixi_90040502_3_dialog_content = "Oi.<sprite=emo_baiyan size=60 />",
  str_homestory_N23paixi_90040502_4_dialog_content = "Hum... Aham!",
  str_homestory_N23paixi_90040502_5_dialog_content = "Você... desenvolveu um interesse no estúdio de cinema ultimamente?",
  str_homestory_N23paixi_90040502_6_dialog_content = "Sim. Ouvi dizer que você poderia atirar em qualquer coisa que quisesse aqui.",
  str_homestory_N23paixi_90040502_7_dialog_content = "Exatamente!",
  str_homestory_N23paixi_90040502_8_dialog_content = "Seja um documentário de suas experiências, ou um sonho que você quer realizar, ou a história de outra pessoa...",
  str_homestory_N23paixi_90040502_9_dialog_content = "O equipamento do nosso estúdio pode ajudá-lo a filmar qualquer coisa!",
  str_homestory_N23paixi_90040502_10_dialog_content = "O que eu preciso fazer?",
  str_homestory_N23paixi_90040502_11_dialog_content = "Hã?",
  str_homestory_N23paixi_90040502_12_dialog_content = "Digamos que eu queira usar o equipamento aqui para documentar coisas que acontecem na vida real e transformá-las em um filme—",
  str_homestory_N23paixi_90040502_13_dialog_content = "Enfim, em algo que serve como documentação vívida.",
  str_homestory_N23paixi_90040502_14_dialog_content = "Se eu quiser fazer isso, o que eu tenho que dar? O que você quer de mim?",
  str_homestory_N23paixi_90040502_15_dialog_content = "Não consigo imaginar que você esteja administrando uma instituição de caridade aqui, afinal.",
  str_homestory_N23paixi_90040502_16_dialog_content = "Aham. Bem, se você está me perguntando quanto custa... É grátis.",
  str_homestory_N23paixi_90040502_17_dialog_content = "Por enquanto, pelo menos!",
  str_homestory_N23paixi_90040502_18_dialog_content = "Quanto ao futuro...",
  str_homestory_N23paixi_90040502_19_dialog_content = "Decidiremos se queremos cobrar fora do Cloud Gardens assim que entendermos as operações...",
  str_homestory_N23paixi_90040502_20_dialog_content = "Mm... vamos pensar sobre essas coisas mais tarde.",
  str_homestory_N23paixi_90040502_21_dialog_content = "Tudo o que você precisa saber é que, por enquanto, nosso estúdio é gratuito!",
  str_homestory_N23paixi_90040502_22_dialog_content = "Ah?",
  str_homestory_N23paixi_90040502_23_dialog_content = "Simplificando, se há um filme que você deseja fazer, tudo o que você precisa fazer é enviar o roteiro e os adereços para nós.",
  str_homestory_N23paixi_90040502_24_dialog_content = "Claro, se você não tiver os adereços necessários, posso ajudar a reunir materiais para fazê-los.",
  str_homestory_N23paixi_90040502_25_dialog_content = "Ou, se você não sabe escrever um script... eu também posso tentar...",
  str_homestory_N23paixi_90040502_26_dialog_content = "Você sabe... ajudar a reunir alguma inspiração... ou algo assim.",
  str_homestory_N23paixi_90040502_27_dialog_content = "Quer dizer que eu não tenho que levantar um dedo?",
  str_homestory_N23paixi_90040502_28_dialog_content = "E-é isso que eu acabei de dizer?",
  str_homestory_N23paixi_90040502_29_dialog_content = "Não é basicamente isso que você está dizendo?",
  str_homestory_N23paixi_90040502_30_dialog_content = "Eu...",
  str_homestory_N23paixi_90040502_31_dialog_content = "Estou brincando.",
  str_homestory_N23paixi_90040502_32_dialog_content = "Eu... realmente não posso dizer pela seriedade em seu rosto.",
  str_homestory_N23paixi_90040502_33_dialog_content = "Eu tenho um roteiro pronto.",
  str_homestory_N23paixi_90040502_34_dialog_content = "O que eu preciso é de inspiração, de preferência coisas que sejam verdadeiras e críveis.",
  str_homestory_N23paixi_90040502_35_dialog_content = "A rigor, o filme que quero fazer... deveria ser algo como um documentário.",
  str_homestory_N23paixi_90040502_36_dialog_content = "Um documentário?",
  str_homestory_N23paixi_90040502_37_dialog_content = "Uhum.",
  str_homestory_N23paixi_90040502_38_dialog_content = "Entendo...",
  str_homestory_N23paixi_90040502_39_dialog_content = "Tudo bem, entendido.",
  str_homestory_N23paixi_90040502_40_dialog_content = "Não se preocupe. Eu já fiz isso antes!",
  str_homestory_N23paixi_90040502_41_dialog_content = "Então, qual vida cotidiana você quer que eu pesquise como sua inspiração?",
  str_homestory_N23paixi_90040502_42_dialog_content = "<color=#FFB400>Sikare.</color>",
  str_homestory_N23paixi_90040502_43_dialog_content = "... S-Sikare!?",
  str_homestory_N23paixi_90040502_44_dialog_content = "Existe um problema? Pessoas de diferentes profissões certamente levam vidas diferentes.",
  str_homestory_N23paixi_90040502_45_dialog_content = "N-Sem problemas...",
  str_homestory_N23paixi_90040502_46_dialog_content = "E obviamente, você está mais perto dela do que eu.",
  str_homestory_N23paixi_90040502_47_dialog_content = "É por isso que você é melhor para o trabalho.",
  str_homestory_N23paixi_90040502_48_dialog_content = "Tudo bem, entendido.",
  str_homestory_N23paixi_90040502_49_dialog_content = "Obrigado.",
  str_homestory_N23paixi_90040502_50_dialog_content = "Estarei esperando aqui.",
  str_homestory_N23paixi_90040503_1_dialog_content = "Bola de neve?",
  str_homestory_N23paixi_90040503_2_dialog_content = "Olá, Sikare.",
  str_homestory_N23paixi_90040503_3_dialog_content = "Há quanto tempo.",
  str_homestory_N23paixi_90040503_4_dialog_content = "A vida idiota mas feliz daquelas paramecias também chegou a você, né?",
  str_homestory_N23paixi_90040503_5_dialog_content = "Eu...",
  str_homestory_N23paixi_90040503_6_dialog_content = "Não tenho ideia de como responder a isso.",
  str_homestory_N23paixi_90040503_7_dialog_content = "Eu entendo. Você compartilha \"laços de amizade\" com eles.",
  str_homestory_N23paixi_90040503_8_dialog_content = "Então, por que você tá aqui?",
  str_homestory_N23paixi_90040503_9_dialog_content = "Bola de Neve, você realmente é especial, diferente daquele grupo.",
  str_homestory_N23paixi_90040503_10_dialog_content = "Não tenho vontade nem de falar com eles. Não suporto o cheiro de paramecia neles.",
  str_homestory_N23paixi_90040503_11_dialog_content = "Certo... Deixe-me ser franco, Sikare.",
  str_homestory_N23paixi_90040503_12_dialog_content = "Paloma quer que eu pergunte como é seu dia a dia.",
  str_homestory_N23paixi_90040503_13_dialog_content = "Por favor, não entenda mal! Ela só quer fazer um documentário sobre o cotidiano de todos os tipos de pessoas.",
  str_homestory_N23paixi_90040503_14_dialog_content = "Então... ela me pediu para descobrir sobre o seu.",
  str_homestory_N23paixi_90040503_15_dialog_content = "Paloma... Eu sei quem ela é.",
  str_homestory_N23paixi_90040503_16_dialog_content = "Nós já nos conhecemos. Apenas algumas vezes, no entanto.",
  str_homestory_N23paixi_90040503_17_dialog_content = "Parece que ela é um pouco mais esperta que o resto da paramecia.",
  str_homestory_N23paixi_90040503_18_dialog_content = "No mínimo, ela era esperta o suficiente para saber que receberia suas respostas se mandasse você.",
  str_homestory_N23paixi_90040503_19_dialog_content = "Mas tenha isso em mente, Bola de Neve.",
  str_homestory_N23paixi_90040503_20_dialog_content = "A única razão pela qual estou respondendo as perguntas dela é porque você é quem está me perguntando.",
  str_homestory_N23paixi_90040503_21_dialog_content = "Certo. Obrigado, Sikare.",
  str_homestory_N23paixi_90040503_22_dialog_content = "Começo meus dias conversando com Faria.",
  str_homestory_N23paixi_90040503_23_dialog_content = "Se estou de bom humor, não faço nada além de olhar para o céu pacífico.<sprite=emo_pugongying size=60 />",
  str_homestory_N23paixi_90040503_24_dialog_content = "Se estou de mau humor... o céu aqui não é capaz de me satisfazer.",
  str_homestory_N23paixi_90040503_25_dialog_content = "Depois vou para onde pertenço e conto a Faria as histórias que ouvi.",
  str_homestory_N23paixi_90040503_26_dialog_content = "Sobre o mundo exterior, sobre o céu que muda de cor, as árvores que perdem suas folhas e...",
  str_homestory_N23paixi_90040503_27_dialog_content = "Pessoas que andam na terra.",
  str_homestory_N23paixi_90040503_28_dialog_content = "Assim são os meus dias.",
  str_homestory_N23paixi_90040503_29_dialog_content = "Com certeza avisarei Paloma.",
  str_homestory_N23paixi_90040503_30_dialog_content = "Acho que ela ficará satisfeita com esta resposta.",
  str_homestory_N23paixi_90040503_31_dialog_content = "Hã?",
  str_homestory_N23paixi_90040503_32_dialog_content = "Você não vai me dar o mesmo olhar lamentável que todas as outras paramécias fazem?",
  str_homestory_N23paixi_90040503_33_dialog_content = "Eu não olharia para você assim.",
  str_homestory_N23paixi_90040503_34_dialog_content = "Citando Paloma...",
  str_homestory_N23paixi_90040503_35_dialog_content = "\"Pessoas de diferentes profissões certamente levam vidas diferentes.\"",
  str_homestory_N23paixi_90040503_36_dialog_content = "Então, se é assim que seu dia é e se você não consegue mudá-lo, desejo que você seja feliz todos os dias.",
  str_homestory_N23paixi_90040503_37_dialog_content = "...",
  str_homestory_N23paixi_90040503_38_dialog_content = "Você certamente é diferente dos outros, Bola de Neve.",
  str_homestory_N23paixi_90040504_1_dialog_content = "PlayerName.",
  str_homestory_N23paixi_90040504_2_dialog_content = "Hum...",
  str_homestory_N23paixi_90040504_3_dialog_content = "...",
  str_homestory_N23paixi_90040504_4_dialog_content = "... Então é assim que são os dias de Sikare.",
  str_homestory_N23paixi_90040504_5_dialog_content = "Entendi.",
  str_homestory_N23paixi_90040504_6_dialog_content = "Obrigado por me ajudar com a pesquisa.",
  str_homestory_N23paixi_90040504_7_dialog_content = "Eu vou ter certeza de usá-lo no meu script.",
  str_homestory_N23paixi_90040504_8_dialog_content = "Você o terá em breve, junto com os adereços que preparei.",
  str_homestory_N23paixi_90040504_9_dialog_content = "Tá bom.",
  str_homestory_N23paixi_90040504_10_dialog_content = "E depois disso... deixarei meu documentário em suas măos competentes.",
  str_homestory_N23paixi_90040504_11_dialog_content = "Certo! Sem problemas!",
  str_homestory_N23paixi_90040504_12_dialog_content = "Obrigada, PlayerName.",
  str_homestory_N23paixi_90040505_1_dialog_content = "Ei, PlayerName. Como foi?",
  str_homestory_N23paixi_90040505_2_dialog_content = "Bem, você estava certo.",
  str_homestory_N23paixi_90040505_3_dialog_content = "Paloma queria fazer um filme.",
  str_homestory_N23paixi_90040505_4_dialog_content = "Mas ela precisava de material inspirador especial, então eu a ajudei.",
  str_homestory_N23paixi_90040505_5_dialog_content = "Uau!",
  str_homestory_N23paixi_90040505_6_dialog_content = "Mas tudo isso está feito agora!",
  str_homestory_N23paixi_90040505_7_dialog_content = "O roteiro dela também está pronto.",
  str_homestory_N23paixi_90040505_8_dialog_content = "Ela até disse que ia nos fornecer os adereços.",
  str_homestory_N23paixi_90040505_9_dialog_content = "Uau!!",
  str_homestory_N23paixi_90040505_10_dialog_content = "Ela deve ser rica!<sprite=emo_baiyebi size=60 />",
  str_homestory_N23paixi_90040505_11_dialog_content = "Eu realmente não sei sobre isso.",
  str_homestory_N23paixi_90040505_12_dialog_content = "Mas ela não poderia ser mais pobre do que nós dois.",
  str_homestory_N23paixi_90040505_13_dialog_content = "Estou tão ciumento!",
  str_homestory_N23paixi_90040505_14_dialog_content = "Bem, de qualquer forma, estou todo animado agora!",
  str_homestory_N23paixi_90040505_15_dialog_content = "Vou adquirir todos os tipos de habilidades e ganhar muito dinheiro com minhas próprias habilidades!",
  str_homestory_N23paixi_90040505_16_dialog_content = "PlayerName, vamos colocar a câmera rodando assim que conseguirmos os adereços.",
  str_homestory_N23paixi_90040505_17_dialog_content = "Sim!",
  str_homestory_N23paixi_90040601_1_dialog_content = "Meu querido amigo!",
  str_homestory_N23paixi_90040601_2_dialog_content = "Caronte!",
  str_homestory_N23paixi_90040601_3_dialog_content = "Você também quer fazer um filme?",
  str_homestory_N23paixi_90040601_4_dialog_content = "Um filme?",
  str_homestory_N23paixi_90040601_5_dialog_content = "Não não não, PlayerName.",
  str_homestory_N23paixi_90040601_6_dialog_content = "Eu estava apenas admirando o toca-discos aqui.<sprite=emo_yinfu size=60 />",
  str_homestory_N23paixi_90040601_7_dialog_content = "Certo. Lembro que você era fã disso.",
  str_homestory_N23paixi_90040601_8_dialog_content = "Uma vez.",
  str_homestory_N23paixi_90040601_9_dialog_content = "Uma vez eu considerei aquele toca-discos como minha coisa favorita no mundo!",
  str_homestory_N23paixi_90040601_10_dialog_content = "Hã?",
  str_homestory_N23paixi_90040601_11_dialog_content = "Espere. Isso significa que você se apaixonou por outro toca-discos?",
  str_homestory_N23paixi_90040601_12_dialog_content = "De nada, meu caro amigo.",
  str_homestory_N23paixi_90040601_13_dialog_content = "Eu sou uma pessoa muito leal.",
  str_homestory_N23paixi_90040601_14_dialog_content = "Dito isso, acredito que esse toca-discos poderia usar algumas melhorias.",
  str_homestory_N23paixi_90040601_15_dialog_content = "Como assim?",
  str_homestory_N23paixi_90040601_16_dialog_content = "Você construiu um novo centro de artes aqui. Aquela estrutura encantadora dificilmente poderia escapar dos meus olhos.",
  str_homestory_N23paixi_90040601_17_dialog_content = "Mas isso me fez pensar na outra obra de arte em Cloud Gardens – o toca-discos, é claro. Poderia realmente usar uma atualização.",
  str_homestory_N23paixi_90040601_18_dialog_content = "Oh! Música e filmes!",
  str_homestory_N23paixi_90040601_19_dialog_content = "Somente quando combinados podem enfeitar este lugar com a luz mais glamourosa!",
  str_homestory_N23paixi_90040601_20_dialog_content = "Uhm... Ok, eu posso ver seu raciocínio por trás disso.",
  str_homestory_N23paixi_90040601_21_dialog_content = "Mas eu realmente não sei muito sobre música. Como você acha que devemos melhorar o toca-discos?",
  str_homestory_N23paixi_90040601_22_dialog_content = "Meu amigo, nada me dá mais prazer do que responder a esta sua pergunta.",
  str_homestory_N23paixi_90040601_23_dialog_content = "Ajustes podem ser feitos para que suas engrenagens funcionem com mais precisão, fazendo com que a música soe ainda melhor...",
  str_homestory_N23paixi_90040601_24_dialog_content = "Oh, o mero pensamento disso me excita!<sprite=emo_aixin size=60 />",
  str_homestory_N23paixi_90040601_25_dialog_content = "Você detalharia mais sobre isso?",
  str_homestory_N23paixi_90040601_26_dialog_content = "Vejo que você está tão animado quanto eu!",
  str_homestory_N23paixi_90040601_27_dialog_content = "Bom! Então não vamos perder mais tempo!",
  str_homestory_N23paixi_90040601_28_dialog_content = "Claro, você pode deixar os ajustes para mim.",
  str_homestory_N23paixi_90040601_29_dialog_content = "Mas vou precisar que você cuide de algo pequeno.",
  str_homestory_N23paixi_90040601_30_dialog_content = "Primeiro, vou precisar de um pouco de água.",
  str_homestory_N23paixi_90040601_31_dialog_content = "Nós precisamos <color=#FFB400>arrume os arredores do toca-discos</color>.",
  str_homestory_N23paixi_90040601_32_dialog_content = "Dessa forma, ele pode retornar ao seu antigo eu radiante no abraço de um ambiente limpo.",
  str_homestory_N23paixi_90040601_33_dialog_content = "Claro, sem problemas.",
  str_homestory_N23paixi_90040601_34_dialog_content = "Então, vou dedicar um tempo para estudar aquele lindo toca-discos...",
  str_homestory_N23paixi_90040601_35_dialog_content = "e ponderar sobre como torná-lo ainda mais radiante.",
  str_homestory_N23paixi_90040602_1_dialog_content = "Eu sei que você nunca decepcionaria um artista.",
  str_homestory_N23paixi_90040602_2_dialog_content = "Isso mesmo. ({1}/{2})",
  str_homestory_N23paixi_90040602_5_dialog_content = "Excelente.",
  str_homestory_N23paixi_90040602_6_dialog_content = "Agora que temos água, podemos arrumar os arredores do toca-discos.",
  str_homestory_N23paixi_90040602_7_dialog_content = "Sim!",
  str_homestory_N23paixi_90040602_8_dialog_content = "Vou pegar a área externa. Vou deixar a área perto do toca-discos para você, certo?",
  str_homestory_N23paixi_90040602_9_dialog_content = "Na verdade, por que você não deixa toda a limpeza para mim, meu querido amigo?",
  str_homestory_N23paixi_90040602_10_dialog_content = "Huh? Por quê?",
  str_homestory_N23paixi_90040602_11_dialog_content = "Acredito que o toca-discos precisa de um polimento para exalar toda a sua beleza sedutora e glamorosa.",
  str_homestory_N23paixi_90040602_12_dialog_content = "Acho que vamos precisar de alguns <color=#FFB400>minério</color>.",
  str_homestory_N23paixi_90040602_13_dialog_content = "Você quer polir o toca-discos com minério?",
  str_homestory_N23paixi_90040602_14_dialog_content = "Isso mesmo, meu caro amigo.",
  str_homestory_N23paixi_90040602_15_dialog_content = "Eu não tenho ideia do que você está pensando, mas, novamente, também não consigo encontrar nenhuma falha nisso.",
  str_homestory_N23paixi_90040602_16_dialog_content = "Ah, eu prometo, você vai entender assim que ver os resultados.",
  str_homestory_N23paixi_90040602_17_dialog_content = "Tudo bem. Eu confio em você.",
  str_homestory_N23paixi_90040602_18_dialog_content = "O ambiente ao redor do toca-discos foi limpo... mas está longe de ser suficiente!",
  str_homestory_N23paixi_90040602_19_dialog_content = "Ainda está a alguma distância de alcançar o objetivo final brilhante.",
  str_homestory_N23paixi_90040602_20_dialog_content = "Sim.",
  str_homestory_N23paixi_90040602_3_dialog_content = "Um momento...",
  str_homestory_N23paixi_90040602_4_dialog_content = "Certo. Vou esperar aqui em antecipação um pouco mais, então.",
  str_homestory_N23paixi_90040603_1_dialog_content = "Eu sei que você não vai decepcionar um artista.",
  str_homestory_N23paixi_90040603_2_dialog_content = "Isso mesmo. ({1}/{2})",
  str_homestory_N23paixi_90040603_5_dialog_content = "Ótimo.",
  str_homestory_N23paixi_90040603_6_dialog_content = "Os materiais estão todos prontos!",
  str_homestory_N23paixi_90040603_7_dialog_content = "Querido amigo, devo agradecer-lhe muito por apoiar o meu sonho.",
  str_homestory_N23paixi_90040603_8_dialog_content = "É aqui?",
  str_homestory_N23paixi_90040603_9_dialog_content = "De uma vez só.",
  str_homestory_N23paixi_90040603_10_dialog_content = "Enquanto você estava ocupado me ajudando a alcançar meu sonho, eu descobri como podemos atualizar esse lindo toca-discos.",
  str_homestory_N23paixi_90040603_11_dialog_content = "Tudo que você tem a fazer agora é esperar.",
  str_homestory_N23paixi_90040603_12_dialog_content = "Então tá.",
  str_homestory_N23paixi_90040603_13_dialog_content = "Obrigado, Caronte!",
  str_homestory_N23paixi_90040603_14_dialog_content = "Sou eu quem deveria estar lhe agradecendo.",
  str_homestory_N23paixi_90040603_3_dialog_content = "Espere um segundo...",
  str_homestory_N23paixi_90040603_4_dialog_content = "Ah, vou esperar aqui um pouco mais, então.",
  str_homestory_N23paixi_90040604_1_dialog_content = "Uau, PlayerName!",
  str_homestory_N23paixi_90040604_2_dialog_content = "Muitos aurorianos estiveram em nosso estúdio de cinema!",
  str_homestory_N23paixi_90040604_3_dialog_content = "Sim! Vice, você viu os filmes que eles fizeram?",
  str_homestory_N23paixi_90040604_4_dialog_content = "Espere. Você quer dizer que eles não estavam apenas visitando o lugar, mas que eles realmente fizeram filmes?",
  str_homestory_N23paixi_90040604_5_dialog_content = "Exatamente!",
  str_homestory_N23paixi_90040604_6_dialog_content = "Isso é incrível, PlayerName!",
  str_homestory_N23paixi_90040604_7_dialog_content = "Hahaha. Bem, foi idéia sua, então não posso levar todo o crédito.",
  str_homestory_N23paixi_90040604_8_dialog_content = "É um pouco egoísta se elogiar, mas ainda tenho que dizer: Veja, eu avisei!",
  str_homestory_N23paixi_90040604_9_dialog_content = "Todo mundo tem experiências que deseja documentar visualmente!",
  str_homestory_N23paixi_90040604_10_dialog_content = "Você tem razão.",
  str_homestory_N23paixi_90040604_11_dialog_content = "Ah, mas falando nisso...",
  str_homestory_N23paixi_90040604_12_dialog_content = "Você tem trabalhado duro, não tem?",
  str_homestory_N23paixi_90040604_13_dialog_content = "Posso arriscar um palpite.",
  str_homestory_N23paixi_90040604_14_dialog_content = "Deve ter sido um trabalho árduo colocar o estúdio de cinema em funcionamento a partir do estado em que estava no início.",
  str_homestory_N23paixi_90040604_15_dialog_content = "Ah! Bem, tudo o que fiz foi reunir materiais e fazer alguns recados.",
  str_homestory_N23paixi_90040604_16_dialog_content = "Minos, Lilica, Hedy, Sadie, Paloma e Charon cuidaram da maioria das coisas técnicas.",
  str_homestory_N23paixi_90040604_17_dialog_content = "Todos são incríveis!",
  str_homestory_N23paixi_90040604_18_dialog_content = "Então PlayerName, você já viu todos os filmes que eles fizeram?",
  str_homestory_N23paixi_90040604_19_dialog_content = "Não na íntegra, não.",
  str_homestory_N23paixi_90040604_20_dialog_content = "Quer dizer, eu sei sobre o que são os filmes deles, mas...",
  str_homestory_N23paixi_90040604_21_dialog_content = "Não tive oportunidade de ver como ficaram.",
  str_homestory_N23paixi_90040604_22_dialog_content = "Nós iremos! Aqui está sua chance!",
  str_homestory_N23paixi_90040604_23_dialog_content = "Que tal irmos assisti-los juntos?",
  str_homestory_N23paixi_90040604_24_dialog_content = "Beleza!"
}
return config
